-- Políticas restritivas: mantêm as políticas globais existentes para dados legados
-- e para a conta de serviço, mas isolam dados que já possuem room_id.
create policy players_room_select_gate on public.players as restrictive for select to authenticated using (room_id is null or public.current_user_role() = 'admin' or (select public.is_room_member(room_id)));
create policy championships_room_select_gate on public.championships as restrictive for select to authenticated using (room_id is null or public.current_user_role() = 'admin' or (select public.is_room_member(room_id)));
create policy matches_room_select_gate on public.matches as restrictive for select to authenticated using (room_id is null or public.current_user_role() = 'admin' or (select public.is_room_member(room_id)));
create policy fixtures_room_select_gate on public.fixtures as restrictive for select to authenticated using (room_id is null or public.current_user_role() = 'admin' or (select public.is_room_member(room_id)));
create policy championship_participants_room_select_gate on public.championship_participants as restrictive for select to authenticated using (room_id is null or public.current_user_role() = 'admin' or (select public.is_room_member(room_id)));

create policy players_room_write_gate on public.players as restrictive for all to authenticated using (room_id is null or public.current_user_role() = 'admin' or public.room_member_role(room_id) in ('owner', 'admin')) with check (room_id is null or public.current_user_role() = 'admin' or public.room_member_role(room_id) in ('owner', 'admin'));
create policy championships_room_write_gate on public.championships as restrictive for all to authenticated using (room_id is null or public.current_user_role() = 'admin' or public.room_member_role(room_id) in ('owner', 'admin')) with check (room_id is null or public.current_user_role() = 'admin' or public.room_member_role(room_id) in ('owner', 'admin'));
create policy matches_room_write_gate on public.matches as restrictive for all to authenticated using (room_id is null or public.current_user_role() = 'admin' or public.room_member_role(room_id) in ('owner', 'admin')) with check (room_id is null or public.current_user_role() = 'admin' or public.room_member_role(room_id) in ('owner', 'admin'));
create policy fixtures_room_write_gate on public.fixtures as restrictive for all to authenticated using (room_id is null or public.current_user_role() = 'admin' or public.room_member_role(room_id) in ('owner', 'admin')) with check (room_id is null or public.current_user_role() = 'admin' or public.room_member_role(room_id) in ('owner', 'admin'));
create policy championship_participants_room_write_gate on public.championship_participants as restrictive for all to authenticated using (room_id is null or public.current_user_role() = 'admin' or public.room_member_role(room_id) in ('owner', 'admin')) with check (room_id is null or public.current_user_role() = 'admin' or public.room_member_role(room_id) in ('owner', 'admin'));

create policy players_room_organizer_write on public.players for all to authenticated using (room_id is not null and public.room_member_role(room_id) in ('owner', 'admin')) with check (room_id is not null and public.room_member_role(room_id) in ('owner', 'admin'));
create policy championships_room_organizer_write on public.championships for all to authenticated using (room_id is not null and public.room_member_role(room_id) in ('owner', 'admin')) with check (room_id is not null and public.room_member_role(room_id) in ('owner', 'admin'));
create policy matches_room_organizer_write on public.matches for all to authenticated using (room_id is not null and public.room_member_role(room_id) in ('owner', 'admin')) with check (room_id is not null and public.room_member_role(room_id) in ('owner', 'admin'));
create policy fixtures_room_organizer_write on public.fixtures for all to authenticated using (room_id is not null and public.room_member_role(room_id) in ('owner', 'admin')) with check (room_id is not null and public.room_member_role(room_id) in ('owner', 'admin'));
create policy championship_participants_room_organizer_write on public.championship_participants for all to authenticated using (room_id is not null and public.room_member_role(room_id) in ('owner', 'admin')) with check (room_id is not null and public.room_member_role(room_id) in ('owner', 'admin'));
